#include <iostream>
#include <queue>
using namespace std;
char mazeA[20][20], mazeB[20][20];
queue<pair<int,int>> q;
int distanceA[20][20], distanceB[11][11][11][11];
int deltaX[4]={-1,1,0,0}, deltaY[4]={0,0,-1,1};
struct Edge {
    int from, to, flow, capacity, next;
} edges[200005];
int edgeIdx, head[505], parent[505], visited[505], source=501, sink=502, maxFlowResult, n, m, level[505];

inline void addEdge(int u, int v, int w) {
    edges[++edgeIdx]={u,v,0,w,head[u]};
    head[u]=edgeIdx;
    edges[++edgeIdx]={v,u,0,0,head[v]};
    head[v]=edgeIdx;
}

inline bool bfs() {
    queue<int> q2;
    for(int i=0;i<=sink;i++) { visited[i]=0; level[i]=0; }
    q2.push(source);
    visited[source]=1;
    level[source]=1;
    while(!q2.empty()) {
        int x=q2.front(); q2.pop();
        for(int i=head[x];i;i=edges[i].next) {
            if(!visited[edges[i].to] && edges[i].flow<edges[i].capacity) {
                parent[edges[i].to]=i;
                q2.push(edges[i].to);
                visited[edges[i].to]=1;
                level[edges[i].to]=level[x]+1;
                if(edges[i].to==sink) return true;
            }
        }
    }
    return false;
}

inline int dfs(int x, int flow) {
    if(x==sink || flow==0) return flow;
    int remaining=flow;
    for(int i=head[x];i;i=edges[i].next) {
        if(edges[i].capacity>edges[i].flow && level[edges[i].to]==level[x]+1) {
            int delta=dfs(edges[i].to, min(remaining, edges[i].capacity - edges[i].flow));
            if(delta==0) level[edges[i].to]=0;
            edges[i].flow+=delta;
            edges[((i-1)^1)+1].flow-=delta;
            remaining-=delta;
            if(remaining==0) break;
        }
    }
    return flow - remaining;
}

inline void computeMaxFlow() {
    while(bfs()) maxFlowResult+=dfs(source, 1000000007);
}

int main() {
    int n, t;
    cin >> n >> t;
    for(int i=1;i<=n;i++) {
        for(int j=1;j<=n;j++) {
            distanceA[i][j]=10000;
            cin >> mazeA[i][j];
            if(mazeA[i][j]=='Z') {
                q.push({i,j});
                distanceA[i][j]=0;
            }
            if(mazeA[i][j]<='9') addEdge(source, (i-1)*n+j, mazeA[i][j]-'0');
        }
    }
    while(!q.empty()) {
        int x=q.front().first, y=q.front().second; q.pop();
        for(int i=0;i<4;i++) {
            int nx=x+deltaX[i], ny=y+deltaY[i];
            if(nx>0 && ny>0 && nx<=n && ny<=n && mazeA[nx][ny]<='9' && distanceA[nx][ny]>distanceA[x][y]+1) {
                distanceA[nx][ny]=distanceA[x][y]+1;
                q.push({nx,ny});
            }
        }
    }
    for(int i=1;i<=n;i++) {
        for(int j=1;j<=n;j++) {
            if(mazeA[i][j]>'9') continue;
            for(int k=1;k<=n;k++)
                for(int l=1;l<=n;l++)
                    distanceB[i][j][k][l]=10000;
            q.push({i,j});
            distanceB[i][j][i][j]=0;
            while(!q.empty()) {
                int x=q.front().first, y=q.front().second; q.pop();
                for(int f=0;f<4;f++) {
                    int nx=x+deltaX[f], ny=y+deltaY[f];
                    if(nx>0 && ny>0 && nx<=n && ny<=n && mazeA[nx][ny]<='9' && distanceB[i][j][nx][ny]>distanceB[i][j][x][y]+1 && distanceA[x][y]<distanceA[nx][ny]) {
                        distanceB[i][j][nx][ny]=distanceB[i][j][x][y]+1;
                        q.push({nx,ny});
                    }
                }
            }
            for(int k=1;k<=n;k++) {
                for(int l=1;l<=n;l++) {
                    if(distanceB[i][j][k][l]<=min(distanceA[k][l], t))
                        addEdge((i-1)*n+j, (k-1)*n+l+100, 10000);
                }
            }
        }
    }
    for(int i=1;i<=n;i++) {
        for(int j=1;j<=n;j++) {
            cin >> mazeB[i][j];
            if(mazeB[i][j]<='9') addEdge((i-1)*n+j+100, sink, mazeB[i][j]-'0');
        }
    }
    computeMaxFlow();
    cout << maxFlowResult;
    return 0;
}
